        ["field.main_menu.cyberspace.option.exit"] = "Exit",
        ["field.main_menu.vid_phone.no_contacts"] = "  You currently have|no contacts in Seattle.",
        ["stoker.motel.arrival.title"] = "<The battered sign reads Stoker's Coffin Motel.||Motels like these are cheap, each room only large enough to fit a small bed.||Dumps like these tend to attract the dregs of humanity.>",
        ["stoker.motel.arrival.more"] = "|          < MORE >",
        ["shared.more"] = "|          < MORE >",
        ["stoker.motel.manager.title"] = "<The manager yawns.>||I won't bore you with the welcome speech.||So whadda' ya' want?",
        ["stoker.motel.option.crash"] = "Just looking for a place to crash.",
        ["stoker.motel.option.leave"] = "I'll talk to you later, chum.",
        ["stoker.motel.street-ambush.title"] = "<Some of those dregs leap from the shadows.||You are forced back into the street where they attack!!>",
        ["stoker.motel.room.title"] = "I got a room for 20$, up front.||You interested?",
        ["stoker.motel.option.pay"] = "Easy money, chummer.  I'll pay.",
        ["stoker.motel.package-handoff.title"] = "<Stoker squints at you with his one good eye.>||Here's the package.  Don't slot this up!",
        ["stoker.motel.package-question.title"] = "Do you have the package, breeder?||Or have you lost it?||<He grabs the package from you, checks it, and begrudingly pays for your service.>",
        ["stoker.motel.option.package"] = "I'm here to pick up Michael's stuff.",
        ["stoker.motel.option.debt-payment"] = "Small change.  Slot this cred and I'm gone.",
        ["stoker.motel.option.jump-house"] = "250$?!!  How much could he have stored in one of those rooms?!",
        ["stoker.motel.leave.title"] = "I'll be seeing you, chum.",
        ["stoker.motel.debt.title"] = "So, you're Michael's brother, eh?||Your bro' skipped on paying his bill and I'm holding his stuff 'til I get the back rent.||Lets make a deal.||You pay up the 250$ he owes and I'll fork over his stash.",
        ["stoker.motel.room.paid.title"] = "Hope you brought your own towels.||I've been cleaned out this month.||Enjoy your stay.",
        ["stoker.motel.room.insufficient.title"] = "Your stick seems to be low on creds.||I'm sorry, but we can only board paying customers.",
        ["stoker.motel.jump-house.title"] = "Hey, if you need nuyen head up the street to the Jump House.||Gunderson is always looking for runners.||You'll find him in a booth towards the back of the bar.",
        ["field.maglock.door.title"] = "You are facing a sturdy door held closed by an electro-magnetic lock.",
        ["field.maglock.option.more"] = "|          < MORE >",
        ["field.maglock.no-passkey"] = "Since you do not have a Maglock Passkey, your choices are limited to these three...",
        ["field.maglock.insufficient-passkey"] = "Your Maglock Passkey is not sophisticated enough for this lock, limiting your choices to these three...",
        ["field.interaction.option.electronics"] = "<Use your Electronics skill>",
        ["field.interaction.option.grenade"] = "<Blow the door open with a Frag Grenade!!>",
        ["field.interaction.option.walk-away"] = "<Walk away.>",
        ["field.maglock.passkey.result"] = "Your Maglock Passkey quickly decodes the lock.||A barely audible swish-click tells you the door has been disabled.",
        ["field.maglock.electronics.no-skill"] = "You are not skilled in Electronics!",
        ["field.maglock.electronics.success"] = "You make quick work of the lock with your knowledge of electronics.",
        ["field.maglock.electronics.failure"] = "This attempt at the lock eludes you.  You could try again, but you run the risk of alerting security.",
        ["field.maglock.electronics.alert"] = "You realize that you seriously fragged this attempt at the lock!||Your options seem to be diminishing with every scream of the building's alert klaxon!!",
        ["field.maglock.grenade.unavailable"] = "You do not have a Frag Grenade available to you!",
        ["field.maglock.grenade.result"] = "You take cover after priming and setting the grenade.  The blast rips the door screaming from its hinges!||A blaring alert klaxon barely penetrates your deafened ears.",
        ["field.maglock.already-unlocked"] = "It's lock disengaged, you quickly pry open the Maglock door.",
        ["field.security-terminal.title"] = "You are facing a building Security Terminal.|",
        ["field.security-terminal.failed"] = "<You try to break into the security system but fail miserably. >",
        ["field.security-terminal.alarm-disabled"] = "<You manage to shut down the Alarm System... for the moment.>",
        ["field.security-terminal.system-disabled"] = "<You jam through the system, shutting down the Alarm Sytem and the Security Cameras.>|",
        ["field.security-terminal.files"] = "<You also find files that suggest you should search",
        ["field.security-terminal.floor.0"] = "first floor.>",
        ["field.security-terminal.floor.1"] = "second floor.>",
        ["field.security-terminal.floor.2"] = "third floor.>",
        ["field.security-terminal.floor.3"] = "fourth floor.>",
        ["field.security-terminal.floor.4"] = "fifth floor.>",
        ["field.security-terminal.floor.5"] = "sixth floor.>",
        ["field.mode.little_chiba.description"] = "<Little Chiba's Chop Shop is recognized as one of the most competent cyberware installers in Seattle.||Their technicians and surgeons are extremely skilled, thus they have the ability to install powerful cyberware.>",
        ["field.mode.little_chiba.package_handoff"] = "<The salesman hands you a bulky package.>||Please be careful with this.||It's quite fragile.",
        ["field.mode.little_chiba.package_payment"] = "<The salesman's eyes light up when you hand him the package.>||Domo, chum!||<He tosses you a credstick and rushes into the back with the bundle.>",
        ["redmond.vigore-search.page-0"] = "<This area seems to have been swept with recent activity.||Knowing Vigore must be somewhere around, you start a thorough search of the area.||You get lucky and find a secret entrance to an old fallout shelter.>",
        ["redmond.vigore-search.page-1"] = "<After a quick search of the bunker, you find a copy of your overlay map.||In addition, the landmark map is rolled up with it!||Harlequin should be most interested in this.>",
        ["redmond.vigore-search.page-2"] = "<You leave cautiously, expecting to be jumped at any moment.||Fortunately, your luck holds out, and you leave the area without incident.>",
        ["jump-house.entry"] = "<The Jump House is a typical small bar inside the Barrens.||The standard slime frequent it and an occasional shadowrunner sometimes slips in its entrance.||You see a fat man licking his fingers in the far corner booth.>",
        ["gunderson.greeting"] = "Hoi, friend, don't be so obvious!||Ol' Stoker likes to toss my name around, but if you wanna' stay healthy in the shadows you'd do well to just refer to me as \"Mr. Johnson\".",
        ["gunderson.greeting.continuation"] = "Ol' Stoker likes to toss my name around, but if you wanna' stay healthy in the shadows you'd do well to just refer to me as \"Mr. Johnson\".",
        ["gunderson.greeting.after_information"] = "You just tell me what you need, chum.||I'll do what I can for ya'.",
        ["gunderson.option.information"] = "I'm looking for some information.",
        ["gunderson.option.work"] = "I'm lookin' for some work.",
        ["gunderson.option.leave"] = "I'll talk to you later, chum.",
        ["gunderson.information.opening"] = "Info, eh?||Well, chummer, I might be able to help ya' there.||Since you're pretty green, I'll offer some free advice.||Most Johnsons don't mind tellin' you basic information, so there ain't a charge for that.",
        ["gunderson.information.contacts"] = "But if you want some special contacts, the type who can help you out, well, that costs.||Usually somewhere up in the thousands of nuyen.",
        ["gunderson.information.after_return"] = "Natch, chum.||Gunderson's got a wealth of knowledge.||You want basic info or the type that costs 1000$?",
        ["gunderson.information.option.questions"] = "I need some questions answered.",
        ["gunderson.information.option.contacts"] = "I'm looking for some contacts.",
        ["gunderson.information.option.back"] = "Let's talk about a different subject.",
        ["gunderson.information.page.1"] = "Well, chummer, I might be able to help ya' there.||Since you're pretty green, I'll offer some free advice.||Most Johnsons don't mind tellin' you basic information, so there ain't a charge for that.",
        ["gunderson.information.page.2"] = "Since you're pretty green, I'll offer some free advice.||Most Johnsons don't mind tellin' you basic information, so there ain't a charge for that.",
        ["gunderson.information.page.3"] = "Most Johnsons don't mind tellin' you basic information, so there ain't a charge for that.",
        ["gunderson.information.page.4"] = "Usually somewhere up in the thousands of nuyen.",
        ["gunderson.question.johnson"] = "What exactly is a Mr. Johnson?",
        ["gunderson.answer.johnson"] = "A Johnson is your meal ticket if you're gonna be a shadowrunner.||Let's take me for example.||My name is Gunderson, but you should refer to me as Mr. Johnson, outta respect for my anonymity.",
        ["gunderson.answer.johnson.more"] = "My name is Gunderson, but you should refer to me as Mr. Johnson, outta respect for my anonymity.",
        ["gunderson.work.opening"] = "So you wanna go on a shadowrun, eh?||Well, ol' Gunderson's got a beauty for you.",
        ["gunderson.work.page"] = "Later, chum.",
        ["gunderson.work.followup"] = "<He asks to see your Credstick balance.>||You're a little short on nuyen, chummer.||Maybe you want to do me a favor so you can afford my price.",
        ["gunderson.contacts.introduction"] = "Contacts!  We all need contacts, don't we small-time?||Lemme' give ya' a few words of advice.||New contacts take a while to warm up.||So treat 'em well and they'll do their best for ya'.",
        ["gunderson.contacts.decker_offer"] = "That said, I got a line on a Decker who's pretty hot stuff.||She's done some work for me and can probably teach you a thing o' two about running the Matrix.||Ya want her number for 1000$?",
        ["gunderson.contacts.option.accept"] = "Easy money, chummer.  I'll pay.",
        ["gunderson.contacts.purchase"] = "<He jams your Credstick in the slot, and gives it back after the balance has decreased.>||Now that I've deducted my finders fee from your credstick, I'll place her number in your pocket secretary.||Name's Wilma Temmenhoff. Give her a call and tell her Gunderson sent ya'!",
        ["gunderson.question.answer"] = "Geeze, you are green!||A Johnson is your meal ticket if you're gonna be a shadowrunner.||Let's take me for example.||My name is Gunderson, but you should refer to me as Mr. Johnson, outta respect for my anonymity.",
        ["gunderson.question.followup"] = "I receive jobs from those who don't want to dirty their own hands.||I contract out those same jobs to runners like yourself.||It's a food chain, and you're the little fish.",
        ["gunderson.question.vigore.alternate_response"] = "Hear about the new blood, have you?||He's the new man on the streets.||His contracts seem just a little too good if you ask me.||His profits must be a serious shade of red with the rates he's offering!",
        ["gunderson.question.option.local"] = "I've got another question for you.",
        ["gunderson.question.prompt"] = "Hurry up and ask, then.",
        ["gunderson.question.option.vigore"] = "What do you know about a Johnson named Vigore?",
        ["gunderson.question.option.errascoe"] = "Who's this guy Errascoe?",
        ["gunderson.question.vigore.response"] = "Word on the Johnson grapevine says he was involved in something nastier than any sane Johnson would touch!||They say he's holed up in some secret base in the Rat's Nest.",
        ["gunderson.question.errascoe.response"] = "Strictly small time.||He can get some gear and goods for you, but most of his stuff is second rate and overpriced.||He's set up in an abandoned Greenhouse here in Redmond.",
        ["big-rhino.booth.entry"] = "<You move into the booth.||Bodyguards search for hidden weapons on your body.||When they are satisfied, a voice speaks from the shadows.>",
        ["big-rhino.mortimer.opening"] = "Well, what have we here.||A shadowrunner looking for work?||I'm Mortimer Reed and if you serve me well, we both can make a lot of nuyen.",
        ["big-rhino.mortimer.conditional-opening"] = "Looks like I owe ya' some creds.||<Mortimer makes the transactions and gets back to business>.",
        ["big-rhino.option.information"] = "I'm looking for some information.",
        ["big-rhino.option.work"] = "I'm lookin' for some work.",
        ["big-rhino.option.leave"] = "I'll talk to you later, chum.",
        ["big-rhino.related.restaurant-description"] = "<This restaurant is called The Big Rhino.||It specializes in ork gourmet dishes and is actually quite popular with those who can stomach dishes like live worms and sprouts.>",
        ["big-rhino.related.package-approach"] = "<An ork politely approaches you.||Once told why you're here, he hands over the package.>",
        ["big-rhino.related.maitre-d-offer"] = "<An ork maitre d' asks if he can seat you.||You give him the package and he pays you for your efforts.>",
        ["big-rhino.related.package-payment"] = "You give him the package and he pays you for your efforts.>",
        ["wanderer.vigore_jarl.first-impression"] = "<This Mr. Johnson is obviously well-to-do.||He is dressed to kill in a custom-tailored suit.||The jewelery on his wrist appears worth more than you'll ever have.||His personal bodyguard looks like something from a bad dream.>",
        ["wanderer.vigore_jarl.first-meeting"] = "Let me introduce myself.  I'm Vigore.  My friend here you can call Jarl.||My employer is funding me to see how lucrative this \"Mr. Johnson\" thing can be.||With his generous financial support, my percentages tend to be better than most.",
        ["wanderer.vigore_jarl.opening"] = "Greetings, Joshua!||My buddy, Jarl, was just wondering if you were interested in scoring BIG nuyen tonight?!||<Jarl just scowls.>",
        ["wanderer.vigore_jarl.conditional-opening"] = "Greetings, Joshua!||Looks like I owe ya' some creds.||<He happily completes the transaction.>||Now, what can we do for you?",
        ["wanderer.vigore_jarl.booth-vacated"] = "<The booth that Vigore and Jarl worked out of is now empty.||You ask around, but no one seems to know why they left or where they went.>",
        ["wanderer.vigore_jarl.booth-vacated.option.fixers"] = "I have a fixer I use when I need to do something, uhhh, nefarious.||He gets you the items you need, no questions asked.||Would you like his name?",
        ["icarus-descending.access.blocked"] = "<Two elven bodyguards, so cybered and wired they hum, block your passage to the darkened booth.||You decide that this is not the appropriate time to make friends (or enemies) and move on.>",
        ["icarus-descending.caleb.first-meeting"] = "<In the dark booth, you see a well dressed elf.||Two bodyguards flank him.||They seem ready to spring into action at a moments notice.>",
        ["icarus-descending.caleb.first-meeting.continuation"] = "I'm Caleb Brightmore.||I know you're looking for me and, sad to say, I also know why.||I'm truly sorry about your brother's death.  He was a good friend.||Ours is a dangerous business, too dangerous of late.",
        ["icarus-descending.caleb.opening"] = "<Caleb is in his booth, going over some paperwork>.||It's good to see you again, Joshua-sib.||How can I help you?",
        ["icarus-descending.caleb.post-run-opening"] = "Much thanks for the run, Joshua.||<Caleb is completely professional as well as pleasant with the transactions.>||Is there anything else I can help you with?",
        ["icarus-descending.caleb.information.contacts-offer"] = "All you must do is ask.  I will answer as best I can.||I also have some contacts who may help, but I have to offer them something to show you are serious.||They require 2000$ up front before I can give you any numbers.",
        ["icarus-descending.caleb.work.opening"] = "If your half as good as your brother, there's plenty of work for you in Seattle.||I can always use another good man.||I specialize in Data Steals and other Matrix Runs.||It can be very lucrative.",
        ["icarus-descending.caleb.work.renraku-introduction"] = "As an aside, it appears you may have a score to settle with Renraku.||I may have some business that may pay for your actions against them.",
        ["icarus-descending.caleb.work.renraku-followup"] = "Thus, I propose you focus on them for answers to some of your questions.||But do not be too hasty, Renraku is perhaps the most powerful and dangerous Corporation in Seattle.",
        ["icarus-descending.caleb.work.recommended-run"] = "This run should be right up your alley.",
        ["icarus-descending.caleb.work.matrix-requirement"] = "It looks like you need some experience in the Matrix.||If you accept a job from me you'll need to either buy a Datajack or get yourself a good decker.||Then we can do business.",
        ["icarus-descending.caleb.leave"] = "I look forward to seeing you later.||Be careful out there, Joshua.",
        ["icarus-descending.caleb.transaction"] = "<Caleb deducts the amount from your credstick, and borrows your Pocket Secretary.>||As soon as we're done, I'll set things up.||His number is ready for your use.",
        ["icarus-descending.caleb.option.information"] = "I'm looking for some information.",
        ["icarus-descending.caleb.option.work"] = "I'm lookin' for some work.",
        ["icarus-descending.caleb.option.leave"] = "I'll talk to you later, chum.",
        ["jackals-lantern.old-man.opening"] = "<An old man flashes his gums at you.||His foul breath is air freshener compared to the stench of his withered body.||You decide to find a booth on the far side of the room.>",
        ["vid_phone.option.services"] = "I would like to procure your services.",
        ["vid_phone.option.goodbye"] = "Nice chatting with you.  Goodbye.",
        ["vid_phone.contact.page_next"] = "<Next Screen>",
        ["vid_phone.contact.page_previous"] = "<Prior Screen>",
        ["vid_phone.contact.capt_quinton_jaymes.first_call"] = "<The video display turns on, placing you face to face with the Ex-Merc.>||Who the drek are you?  How did you get my number?||Huh?  Friend o' mine?||Well, get talkin'!",
        ["vid_phone.contact.capt_quinton_jaymes.repeat_call"] = "<The Merc comes on line and snuffs a nico-stick.>||Hey, Shadowboy.||You need some more help?",
        ["vid_phone.contact.alesandro_hobbs.first_call"] = "<The vid-phone comes alive and a well dressed company man appears.>||Alesandro here.||Speak.",
        ["vid_phone.contact.alesandro_hobbs.repeat_call"] = "<Alesandro answers.>||Well, what do you want now?",
        ["vid_phone.contact.sharkey.first_call"] = "<A female voice modulates from the pretty face on the vid.>||Sharky here.  You lookin' for a ride, handsome?",
        ["vid_phone.contact.sharkey.repeat_call"] = "<A female voice modulates from the pretty face on the vid.>||Sharky here.  You lookin' for a ride, handsome?",
        ["vid_phone.contact.kipp_david.first_call"] = "<An eternity passes as the vid-phone beeps the other end.||Finally, Kipp connects.>||I'm kind of busy.||Can we do this another time?",
        ["vid_phone.contact.kipp_david.repeat_call"] = "<The phone engages and Kipp answers.>||I'm busy.||Call back later.",
        ["vid_phone.contact.wilma_temmenhoff.first_call"] = "<You connect to the decker.||She keeps the video display turned off.>||Interface quickly or disconnect.",
        ["vid_phone.contact.wilma_temmenhoff.repeat_call"] = "<Wilma connects, still not engaging her video picture.>||Hey, Joshua.||What's the haps?",
        ["vid_phone.contact.macklemann.first_call"] = "<A large troll answers, looking nervously around as if expecting something bad to happen.>||This is the Sarge.||I'm in a hurry, so talk fast.",
        ["vid_phone.contact.macklemann.repeat_call"] = "<A large troll answers, looking nervously around as if expecting something bad to happen.>||This is the Sarge.||I'm in a hurry, so talk fast.",
        ["vid_phone.contact.gregory_wilns.first_call"] = "<The vid-phone dims, but you can still make out a figure on the other side.>||Who calls me at such a late hour?",
        ["vid_phone.contact.gregory_wilns.repeat_call"] = "<The mage answers.>||Yes?",
        ["vid_phone.contact.mr_faradouchi.first_call"] = "<The vid-phone is blanked.>||Who the frag are you?||<You identify yourself and tell him Mauler sent you.>",
        ["vid_phone.contact.mr_faradouchi.repeat_call"] = "<The vid-phone display remains black as Mr. Faradouchi's gravelly voice resonates from the speaker.>||Well, if it isn't my friend, Joshua.||I am pleased to have you in my family.",
        ["vid_phone.contact.agira_tetsumi.first_call"] = "<The vid-phone is blanked.>||Indentify your purpose.||<You identify yourself and ask to speak to Mr. Tetsumi.>",
        ["vid_phone.contact.agira_tetsumi.repeat_call"] = "<The vid-phone display remains black as Agira Tetsumi's pleasant voice modulates through the speaker.>||Arigato, Joshua-san.||For your devotion, I grant you these things.",
        ["vid_phone.contact.henry_j_culver.first_call"] = "<The vid-phone connects to a vulgar little man.||He notices your ork armband immediately.>||Henry J. Culver at your assistance.",
        ["vid_phone.contact.henry_j_culver.repeat_call"] = "<Culver appears at the other end.>||How may I help you?",
        ["vid_phone.contact.max.first_call"] = "<The connection engages and there is a pale man peering at you from the other end.>||State your business quickly, friend.",
        ["vid_phone.contact.max.repeat_call"] = "<Max the Fixer answers his vid-phone.>||How may I assist you?",
        ["vid_phone.contact.chillicut.first_call"] = "<The dimmed screen of the vid-phone identifies itself.>||Detective Chillicutt.||To whom am I speaking?",
        ["vid_phone.contact.chillicut.repeat_call"] = "<The vid-phone display stays black.>||Chillicutt here.||You may speak freely.",
        ["vid_phone.contact.professor_jefferson.first_call"] = "<You dial Proffessor Jefferson.||After a short delay, he picks up.>||Yes, what is it?||I don't have all day!",
        ["vid_phone.contact.professor_jefferson.repeat_call"] = "<The Professor answers.>||Ah, Joshua, it's you!||What can I do for you?",
        ["vid_phone.capt_quinton_jaymes.services"] = "Whatta' ya' need?||Some info on Hollywood?||Or do you want some serious firepower?||Or do you want me to pass 'long the name of a friend o' mine?",
        ["vid_phone.capt_quinton_jaymes.hollywood_intro"] = "I've done the prison run thing once or twice.||Remember  in 2028?||No?||It was in all the net-reports.||My rep was built on that run, you little punk!",
        ["vid_phone.capt_quinton_jaymes.hollywood_topics"] = "You're makin' me mad.||So apologize nice-like, and I'll tell you the ins and outs of a Hollywood jail break.||Otherwise, go buzz.",
        ["vid_phone.capt_quinton_jaymes.weller_intro"] = "Don't shmooze, boy.  It's ugly!||Anyhow, that Hollywood's a hard nut to crack.||Getting in is tough, especially if you want to go in quiet.||If you can get a friend on the inside, though , you could walk right in.",
        ["vid_phone.capt_quinton_jaymes.weller_result"] = "I'd recommend either a level 4 Maglock passkey to get you through the inner security doors or plenty of grenades.||Bring some friends along.||They can cover while you're pinpointing the location of the inmate you're trying to bust out.",
        ["vid_phone.capt_quinton_jaymes.firepower_intro"] = "I've got a few suppliers who could deliver some quality weaponry.||I don't recommend you buying it for show, though.||These weapons are highly illegal, and you'll be in a world o' hurt if Lone Star catches wind of what you're packin'.",
        ["vid_phone.capt_quinton_jaymes.firepower_items"] = "I've got some Frag Grenades for 400$ and an H&K SMG with laser sighting and gas vent for 1,000$.||Are you interested?",
        ["vid_phone.capt_quinton_jaymes.contacts_offer"] = "I can patch you into a hotshot Rigger.||She can drive anything built and knows the wilderness in these parts like she was born there.||I'll only charge ya' 2,800$.",
        ["vid_phone.capt_quinton_jaymes.purchase_result"] = "Just pick a target and party!",
        ["vid_phone.capt_quinton_jaymes.sharkey_result"] = "Okay, her street name is Sharkey.||Here's her number.||<You put the name and number in your Pocket Secretary.>",
        ["vid_phone.capt_quinton_jaymes.purchase.insufficient"] = "Ya' can't pay me with hot air, Shadowboy.||Call me when ya' get some dough.",
        ["vid_phone.capt_quinton_jaymes.purchase.out_of_stock"] = "Uh-oh, Shadowboy, looks like I'm outta' stock.||Try me later after I've replenished my inventory.",
        ["vid_phone.capt_quinton_jaymes.services.disconnected"] = "<You are disconnected without another word.>",
        ["vid_phone.capt_quinton_jaymes.option.hollywood_information"] = "I need info on Hollywood Correctional.",
        ["vid_phone.capt_quinton_jaymes.option.firepower"] = "What items do you have to offer?",
        ["vid_phone.capt_quinton_jaymes.option.contacts"] = "I'm looking for some contacts.",
        ["vid_phone.capt_quinton_jaymes.option.more"] = "|          < MORE >",
        ["vid_phone.capt_quinton_jaymes.option.weller_prison_break"] = "Oh!!  you mean THE Weller prison break!  Legendary!!!",
        ["vid_phone.capt_quinton_jaymes.option.disconnect"] = "Slot off, frag-face!!!",
        ["vid_phone.capt_quinton_jaymes.option.return_to_services"] = "Let's talk about a different subject.",
        ["vid_phone.capt_quinton_jaymes.option.frag_grenades"] = "I'll take the Grenades.",
        ["vid_phone.capt_quinton_jaymes.option.hk227_s"] = "I'll take an SMG.",
        ["vid_phone.capt_quinton_jaymes.option.no_thanks"] = "No.",
        ["vid_phone.capt_quinton_jaymes.option.pay_for_rigger_contact"] = "Easy money, chummer.  I'll pay.",
        ["vid_phone.capt_quinton_jaymes.option.decline_rigger_contact"] = "Neg on that, chum.",
        ["vid_phone.alesandro_hobbs.services"] = "I suppose you want some information on Corporation procedures?||Or would you like to acquire a Maglock Passkey?||Or would you want to meet a Seattle city official?",
        ["vid_phone.alesandro_hobbs.corporation_information"] = "Corps have 2 basic principles of security.||The first is patrols.||Human patrols are the most common, but some Corps use mages, metahumans and possibly paranormal creatures.",
        ["vid_phone.alesandro_hobbs.security_patrols"] = "The first is patrols.||Human patrols are the most common, but some Corps use mages, metahumans and possibly paranormal creatures.",
        ["vid_phone.alesandro_hobbs.security_alerts"] = "If you set off an Active Alert, the security partols are increased, and so are your chances of dying.",
        ["vid_phone.alesandro_hobbs.security_technological"] = "Technological.||They primarily use Maglock systems in security doors to restrict access.||These doors have a variety of ratings, from 1 to 5.||Some Corp doors can be opened with a Maglock passkey of level 2, most with level 3.",
        ["vid_phone.alesandro_hobbs.security_cameras"] = "Another tech trick is to use surveillence cameras.||If you are detected you will set off an Active Alert.But these have limited areas of detection, so it may be possible to sneak around them.",
        ["vid_phone.alesandro_hobbs.passkey_offer"] = "These keys are quite expensive.||10,000$ for level 3 and 20,000$ for level 5!||Are you still interested?",
        ["vid_phone.alesandro_hobbs.purchase.insufficient"] = "<He examines your balance, looks at you briefly, and switches off his vid-phone.>",
        ["vid_phone.alesandro_hobbs.purchase_result"] = "Glad to see I didn't misjudge you.||My delivery boy will have it there in seconds.",
        ["vid_phone.alesandro_hobbs.purchase.out_of_stock"] = "Oops.  Looks like I'm out of those.||Try back later.",
        ["vid_phone.alesandro_hobbs.official_contact_offer"] = "I happen to be on the same wavelength as a fellow public servant of your fair city.||For a token gift of 8,000$, I could give you his name and number.||Interested?",
        ["vid_phone.alesandro_hobbs.macklemann_result"] = "His name is Sergeant Mackelmann, a security guard in Hollywood Correctional.||I'm sure he can reveal many interesting tidbits about avoiding security.",
        ["vid_phone.alesandro_hobbs.option.corporation_information"] = "I want some Coporation information.",
        ["vid_phone.alesandro_hobbs.option.maglock_passkey"] = "I'll take a Maglock passkey.",
        ["vid_phone.alesandro_hobbs.option.seattle_official"] = "I believe I'd be interested in a meeting.",
        ["vid_phone.alesandro_hobbs.option.second_security_type"] = "What is the second type of security?",
        ["vid_phone.alesandro_hobbs.option.security_procedures"] = "Tell me about Corporate security procedures.",
        ["vid_phone.alesandro_hobbs.option.avoid_detection"] = "What about tips to avoid detection.",
        ["vid_phone.alesandro_hobbs.option.pay_for_macklemann"] = "Easy money, chummer.  I'll pay.",
        ["vid_phone.option.more"] = "|          < MORE >",
        ["vid_phone.sharkey.services"] = "You need to bypass the Salish-Shidhe Visa checkpoint?||Or maybe you want me to drop you deep in the woods, like down by the Sinsearach?||I also have a stash you may be interested in.",
        ["vid_phone.sharkey.salish_passage"] = "What's the matter, Lone Star record get a little too long?||I don't really care as long as I get my payment.||I own a chopper, so droppin' you past the checkpoint undetected is a bit tricky, but I can do it for 3,000 large.",
        ["vid_phone.sharkey.sinsearach_passage"] = "I understand completely.  That's quite a haul to do on foot.||Quite a haul in my chopper, also, so the fare'll be 5,000$.",
        ["vid_phone.sharkey.smart_goggles_offer"] = "All I have are some of these Smart Goggles.||They're not as efficient as a Smartlink, but they allow you to operate a SmartGun without getting cybered.||Would you like to buy one for 3,000$?",
        ["vid_phone.sharkey.passage_result"] = "Okay, Hotshot, I'll meet you there in ten.||Climb aboard and I'll have you there faster than you can say Vertical Takeoff and Land!||<She arrives on schedule and you soon arrive in the wilderness.>",
        ["vid_phone.sharkey.insufficient_funds"] = "Listen, chum, I don't do charity work.||If you can't afford it, don't be asking.",
        ["vid_phone.sharkey.smart_goggles_result"] = "Wiz!  I'll have 'em dropped there ASAP.",
        ["vid_phone.sharkey.smart_goggles_inventory_full"] = "Oops.  Looks like I'm out of those.||Try back later.",
        ["vid_phone.sharkey.option.pass_salish"] = "I need to get into the Salish-Shidhe.",
        ["vid_phone.sharkey.option.pass_sinsearach"] = "I need to get to the Sinsearach.",
        ["vid_phone.sharkey.option.smart_goggles"] = "What equipment do you have?",
        ["vid_phone.sharkey.option.pay_for_passage"] = "Easy money, chummer.  I'll pay.",
        ["vid_phone.sharkey.option.return_to_services"] = "Let's talk about a different subject.",
        ["vid_phone.sharkey.option.confirm_purchase"] = "Yes.",
        ["vid_phone.sharkey.option.other_subject"] = "I'll talk to you later, chum.",
        ["vid_phone.kipp_david.intro"] = "<He sighs.>||Yeah, alright, only if it'll be quick.||I'm working on a really wiz program and I don't want to lose my train of thought.",
        ["vid_phone.kipp_david.services"] = "So, I suppose you want to know the secrets of Matrix running the Corps?||Or I could sell you a couple of programs I just finished?||Or are you interested in the hottest cyberdeck on the market?",
        ["vid_phone.kipp_david.matrix_intro"] = "Check.||Since you're friends of Caleb's, I'll fork over the info.",
        ["vid_phone.kipp_david.matrix_corps"] = "The first thing to know about Corp systems is that they are juiced up to the max.||The Corps have all the money in the world, so every one of their systems is pretty much maxed out.||And they're not fools, because they have people like me working for them.",
        ["vid_phone.kipp_david.matrix_result"] = "A lot of that sloppy system construction you've seen earlier does not happen here.||The key to the Corps is high-powered software, and a lot of skill.||Without both of those, the Black Ice will fry you so fast it will make your deck spin.",
        ["vid_phone.kipp_david.program_intro"] = "You may have heard of my latest inventions.||They're called Rebound and Degrade?||I've heard some lower hackers have been pirating my earlier versions, but I have improved them, and they are much better than before.",
        ["vid_phone.kipp_david.program_details"] = "In case you haven't heard of them, Rebound bounces the enemy Ice's attack back at it, allowing you to do more damage in less time.||Degrade attacks the node's security rating, making all programs more effective.",
        ["vid_phone.kipp_david.program_offer"] = "The cost is 30,000$ each.||Well?",
        ["vid_phone.kipp_david.deck_offer"] = "I've got a small supply of one of the rarest things in the sprawl, a Fairlight Excalibur deck.||It is awesome, nothing can touch it, unless you believe the propaganda Fuchi is spreading.||I'd be willing to part with it for 185,000$.",
        ["vid_phone.kipp_david.insufficient_funds"] = "Man, are you wasting my time or what?!||Don't call unless you can come up with some creds!",
        ["vid_phone.kipp_david.disconnected"] = "<You are disconnected without another word.>",
        ["vid_phone.kipp_david.storage_full"] = "Whoa, cyberjock.||Your deck doesn't have the storage for this prog.||You need to upgrade before I can download this to you.",
        ["vid_phone.kipp_david.program_result"] = "Sure thing, chummer.||I've just transferred the program into your cyberdeck.",
        ["vid_phone.kipp_david.option.matrix"] = "Tell me about the Matrix.",
        ["vid_phone.kipp_david.option.programs"] = "Tell me about these experimental programs.",
        ["vid_phone.kipp_david.option.cyberdeck"] = "Tell me about this cyberdeck.",
        ["vid_phone.kipp_david.option.buy_rebound"] = "I'd like to buy Rebound.",
        ["vid_phone.kipp_david.option.buy_degrade"] = "I'd like to buy Degrade.",
        ["vid_phone.kipp_david.option.different_subject"] = "Let's talk about a different subject.",
        ["vid_phone.kipp_david.option.pay_for_deck"] = "Easy money, chummer.  I'll pay.",
        ["vid_phone.wilma_temmenhoff.credstick"] = "Look, I'd rather be jacked into cyberspace, so unless you're gonna make it worth my while, I'm gonna flatline this conversation.||||Slot the 'stick if you wanna keep this line active.||||<You place your credstick in the slot.>",
        ["vid_phone.wilma_temmenhoff.services"] = "Okay, partner, I suppose you want my expert knowledge on the Matrix?||||Or maybe score some experimental software for your deck?",
        ["vid_phone.wilma_temmenhoff.matrix_intro"] = "Sure I can tell you some things to make running the Matrix a bit easier.||||I've done it all, except tangle with the Corps.||||I'm not stupid.",
        ["vid_phone.wilma_temmenhoff.matrix_companies"] = "Okay, chummer, here it is.||||Many small companies are connected to the Matrix, and so they are all open for inspection.||||Most of these companies expand so fast, they jam on a new node and stick some low White Ice in to guard it. ",
        ["vid_phone.wilma_temmenhoff.matrix_sleaze"] = "They're idiots!||||All you have to do is Sleaze or Deceive the White Ice and the Grey will never know!||||Duh!",
        ["vid_phone.wilma_temmenhoff.matrix_result"] = "So always check the end paths.||||Usually you can find a quick way to the CPU much easier then straight through in these poorly defended systems.",
        ["vid_phone.wilma_temmenhoff.program_intro"] = "I've got some new softs like you've never seen!||||The first is Rebound.||||It puts up a shield that deflects incoming attacks back at the Ice.||||It degrades easily, but otherwise it's great!",
        ["vid_phone.wilma_temmenhoff.program_degrade"] = "The other is Degrade.||||This attacks the node itself.||||It kind of short-circuits the security logic, giving your software a better chance to do its thing.",
        ["vid_phone.wilma_temmenhoff.program_offer"] = "I can sell you a level 3 version of either for 5,000$.||||Are you game?",
        ["vid_phone.wilma_temmenhoff.insufficient_funds"] = "You gotta be jokin' me?!||||Can't even afford that paltry amount?||||You're not worth my time.",
        ["vid_phone.wilma_temmenhoff.storage_full"] = "Whoa, cyberjock.||Your deck doesn't have the storage for this prog.||You need to upgrade before I can download this to you.",
        ["vid_phone.wilma_temmenhoff.program_result"] = "Sure thing, chummer.||I've just transferred the program into your cyberdeck.",
        ["vid_phone.wilma_temmenhoff.later"] = "Chat with you later.",
        ["vid_phone.alesandro_hobbs.option.level_3_passkey"] = "Level 3 ($10,000)",
        ["vid_phone.alesandro_hobbs.option.level_5_passkey"] = "Level 5 ($20,000)",
        ["runner.ricky.information.opening"] = "I've lived in Glow City all my life.|I was slummin' in the sewers, but it got me nowhere, because I had no purpose.|And because everyone was larger than me.",
        ["runner.ricky.information.continuation"] = "Then I heard my totem calling.  I have embraced that power, the power of Rat!|Rat has shown that force is not the only way to success.|When I find some companions to work with, I'll be able to use my talents to finally get outta this dump!",
        ["runner.winston_marrs.information.opening"] = "The name's Marrs.  Did you know he was the god of war?  I see things different than most.|The fastest way to solve a problem is to shove a gun in it and shoot!|Problem is, I can't do this all the time.  I run out of bullets too fast.",
        ["runner.winston_marrs.information.continuation"] = "So, I started to think.  How can I get paid to shoot at people?|Then it hit me... join Lone Star!  They can shoot at anyone they like and get free reloads!|So I studied real hard, but you know what?  I was thrown out, so now I'm here looking for work.",
        ["runner.trent.information.opening"] = "My name is Trent.|I've been studying the mystical arts, the powers of magic.|I was studying at the university, but I quickly tired of the parlor tricks they taught there.|I aspired to learn so much more!",
        ["runner.trent.information.continuation"] = "I've decided to add to my experiences by working for those who'll pay for me to have them.",
        ["runner.petr_uvehr.information.opening"] = "I came up here to drown my sorrows.  But I guess you want to talk.|I'm called Petr.  I worked in the tech division of the Stuffer Shack where I learned my way around a cyberdeck.",
        ["runner.petr_uvehr.information.continuation"] = "I was jealous of those cyber-cowboys, with their guns and chrome.|The Matrix got them all they wanted, so I stole me a deck, plugged in, and I've never looked back!",
        ["runner.walking_bear.information.opening"] = "I am Walking Bear.  I was born in the city and was happy until I changed into the form you see now.|Then no one would talk to me and many made fun of me.|I ran into the wilderness and never wanted to return.",
        ["runner.walking_bear.information.continuation"] = "There I met some AmerIndian tribes.  They were nice and taught me the way of the shaman.|Bear reached out to me because he knew I needed his calm words, and he knew I could take care of my AmerIndian brothers.",
        ["runner.phantom.information.opening"] = "I've been shooting the Matrix for a bit.|My handle is Phantom.|Heard of me?",
        ["runner.phantom.information.continuation"] = "I've been making a name for myself in the Matrix.|I worked for a company who trained me in cyberspace.|Then one of those anti-metahuman groups showed up, screaming about purity and them losing jobs and garbage like that.",
        ["runner.two_fists.information.opening"] = "I went to the Barrens to find some action. At the time I thought my life needed some adventure.|Anyway, I get involved with these joyboys who tell me they know how to get their hands on some serious nuyen.",
        ["runner.two_fists.information.continuation"] = "So I hook up with them on this run against Ares, and what do you know?  My buddies set off the alarm while I was checking ahead. Before I knew what hit me, Corp Strike Teams were swarming all over and I end up in Hollywood Pen.",
        ["runner.freya.information.opening"] = "I hear you're the new golden child.  Number one with a bullet, and all that jazz.  So, I guess I can trust you.  I'm Freya.|When I was young, I discovered I had latent magical skills.",
        ["runner.freya.information.continuation"] = "My tribe, the Cascade Crow, viewed hermetic mages as blasphemous, so I ran away and fell in with a radical political group.|They trained me to become an assassin, using magic as my weapon, with Corporate officials as my targets.|I did my job, no sweat.",
        ["runner.rianna.information.opening"] = "Heartbane was an ancient elven leader.|She prophesied the Matrix, \"a place where everything and nothing exists.|A place where wars are fought and blood is shed without weapons\".|She knew it was going to be big!",
        ["runner.rianna.information.continuation"] = "So I use Heartbane as my street name, coupled with my true name, Rianna.|I've been running the Corps since the inception of the Matrix.|I've seen just about every type of IC and flatlined my share of decker cowboys.",
        ["runner.stark.information.opening"] = "I was raised in the AmerIndian lands, and I have spent many years as a tribal warrior. I love my AmerIndian heritage, and will allow nothing to mar it.",
        ["runner.stark.information.continuation"] = "When I heard strangers were entering our land for some unknown purpose, I went to the city to dig up some clues. It was there I met your brother. We became fast friends, and in the end, he was a blood brother.",
        ["runner.ricky.subject.title"] = "Like what?",
        ["runner.ricky.subject.option.shaman_magic"] = "Tell me about shaman magic.",
        ["runner.ricky.subject.option.local_area"] = "Tell me about the local area.",
        ["runner.ricky.subject.option.johnson"] = "Do you know of any Johnsons in the area?",
        ["runner.winston_marrs.subject.title"] = "What do you want?",
        ["runner.winston_marrs.subject.option.halloweeners"] = "Tell me about the Halloweeners.",
        ["runner.winston_marrs.subject.option.lone_star"] = "What do you know about Lone Star?",
        ["runner.winston_marrs.subject.option.troll_origin"] = "How is it that you are a troll?",
        ["runner.trent.subject.title"] = "Yes, like what?",
        ["runner.trent.subject.option.mages"] = "I'd like to hear about mages.",
        ["runner.trent.subject.option.contacts"] = "I'm looking for some contacts.",
        ["runner.trent.subject.option.johnsons"] = "Do you know of any Johnsons in the area?",
        ["runner.ricky.subject.shaman_magic.page_0"] = "Shaman get their powers from nature.|We use her forces to achieve our ends.|This is superior to mages, who force the spirits to do their bidding.",
        ["runner.ricky.subject.shaman_magic.page_1"] = "<He shows you his Rat totem, a dingy block of wood.>|Each shaman has a totem that seeks him out.|This totem represents an animal from nature.|Rat chose me to follow his ways.",
        ["runner.ricky.subject.shaman_magic.page_2"] = "Rat wants me to protect myself by looking for opportunities.|To use guile and misdirection in lieu of combat.|Rat bestows benefits by means of this totem.",
        ["runner.ricky.subject.local_area.page_0"] = "The Rat's Nest is a haven for squatters and other transients.|It used to be the city dump until the city died.|Even I, a follower of Rat, will not hole up there.",
        ["runner.ricky.subject.local_area.page_1"] = "Glow City sprung up when they ran out of room in the Rat's Nest.|Sure, there's some minor radiation leakage from the nuke plant, but it's no big deal.",
        ["runner.ricky.subject.johnson_gunderson.page_0"] = "Yeah, sure.  Gunderson's a Johnson I've used when I needed some quick nuyen.|Works next door at the Jump House, he does.|His payout is as bad as his smell, but his runs are a piece of cake so long as you have some firepower handy when things go sour.",
        ["runner.winston_marrs.subject.halloweeners.page_0"] = "The Halloweeners's own Redmond.  They're the sort of low-end trash I used to hang with before I got more educated.|They beat on unsuspecting targets, but flee when things get too hairy.|Still, they're a lot tougher than the Eye-fivers.",
        ["runner.winston_marrs.subject.lone_star.page_0"] = "Lone Stars!  I hate them!|They think they are so wiz, walking the streets in their regulation body armor and shooting at anyone they want!|I hate them!|Don't bring up that subject again!",
        ["runner.winston_marrs.subject.troll_origin.page_0"] = "<He looks like he's going to lose his temper, but stays calm.>|I didn't ask to be like this, you know.  I was normal, like you, when I was younger.",
        ["runner.winston_marrs.subject.troll_origin.page_1"] = "But now I'm seven feet, four inches of troll.|Do you know how hard it is to buy clothes that fit?!|Arrgh, it's enough to make me want to shoot someone!|<His grip tightens on his pistol.>",
        ["runner.trent.subject.mages.page_0"] = "Mages use arcane magic.  Shaman require a totem, and are forced to adhere to the laws of nature.|Mages have no such limitations.  We use our intellect to call upon the astral plane, and bend it to our will.",
        ["runner.trent.subject.mages.page_1"] = "When I get some more experience, you'll see some serious casting come from my fingers, man!",
        ["runner.trent.subject.contacts.page_0"] = "I've got the number of an old professor of mine, Jefferson is his name.|Most folk'll only sell names to you, but the prof's always willing to talk with new people without the influence of money.|<He places the name in your Pocket Secretary.>",
        ["runner.trent.subject.johnsons.page_0"] = "Yeah, I know of a local Johnson.|Goes by the name of Vigore.|I occasionally see him over in the Rat's Nest, but he does his work out of the Wanderer in Puyallup Barrens.",
