        ["items.action_detail.0"] = "A small, cheap hold-out\npistol.\nLight damage, low power.",
        ["items.action_detail.1"] = "A slim-line personal weapon\nfavored by street thugs.\nLight damage, light power.",
        ["items.action_detail.2"] = "This light design is popular\namong the style-conscious.\nLight damage, light power.",
        ["items.action_detail.3"] = "Designed for light security\nwork.\nLight damage, light power.",
        ["items.action_detail.4"] = "This revolver holds less\nammo but more punch.\nMed damage, brutal power.",
        ["items.action_detail.5"] = "A sturdy weapon that trades\nfirepower for ammo.\nMed damage, high power.",
        ["items.action_detail.6"] = "This menacing gun is popular\namong mercenaries.\nMed damage, high power.",
        ["items.action_detail.7"] = "A common Soviet SMG carbine.\nIt is illegal.\nMed damage, light power.",
        ["items.action_detail.8"] = "This SMG is most favored with\nCorp security.  It is illegal.\nMed damage, medium power.",
        ["items.action_detail.9"] = "A common SMG for street gangs.\nIt is illegal.\nMed damage, light power.",
        ["items.action_detail.10"] = "This autoloading shotgun\nis illegal.\nHigh damage, brutal power.",
        ["items.action_detail.11"] = "This pistol-like shotgun\nis illegal.\nHigh damage, high power.",
        ["items.action_detail.12"] = "This illegal grenade causes\nphys damage in a large area.\nHigh damage, med-high power.",
        ["items.action_detail.13"] = "This grenade casues physical\ndamage in a large area.\nHigh damage, light power.",
        ["items.action_detail.14"] = "This grenade causes stun\ndamage in a large area.\nMed damage, brutal power.",
        ["items.action_detail.15"] = "A portable first aid kit\nthat can heal wounds based\non the users Biotech skill.",
        ["items.action_detail.16"] = "A slap patch that instantly\nincreases mental health\nby 20%.",
        ["items.action_detail.17"] = "A slap patch that instantly\nincreases physical health\nby 20%.",
        ["items.action_detail.18"] = "This item absorbs drain from\nthe casting of a spell.",
        ["items.action_detail.19"] = "This illegal key can open\nMaglocked doors less than or\nequal to its rating.",
        ["items.action_detail.20"] = "This illegal kit increases\nthe chances of opening\nMaglocked doors.",
        ["items.action_detail.21"] = "Though not as efficient as a\nSmartlink, these allow the\nuser to operate a SmartGun.",
        ["items.action_detail.22"] = "A magical weapon that\nenhances the user's accuracy\nand damage.",
        ["items.action_detail.23"] = "A Power Focus increases the\npotency of all spells known\nby the user!",
        ["items.action_detail.24"] = "Spell Foci are used to\nincrease the potency of\ntheir corresponding spells.",
        ["items.action_detail.25"] = "A magical device that reduces\nall types of damage directed\nat the user.",
        ["items.action_detail.26"] = "A magical device that\nenhances the combat ability\nof the user.",
